# Generated by OrchestKit Claude Plugin
# Created: 2026-09-02

#!/usr/bin/env python3
"""Measure prompt-cache eviction exposure from real Claude Code transcripts.

Answers the question behind `promptCacheTtl` / `subagentPromptCacheTtl`
(CC 2.1.243): how much of our cache WRITE volume is a re-write of a prefix
that the 5-minute cache had already evicted, and would a 1-hour TTL pay?

Method. Every assistant turn in `~/.claude/projects/**/*.jsonl` carries a
`usage` block. For each turn we take (a) the gap since the previous assistant
turn in the same transcript and (b) `cache_creation_input_tokens` /
`cache_read_input_tokens`, plus `usage.cache_creation.ephemeral_5m/1h_input_tokens`,
which names the TTL each write actually used. A turn after a gap longer than
the TTL that shows creation >> read is a prefix RE-WRITE. Main sessions and
subagent transcripts (agent-*.jsonl) are reported separately because CC
caches them on different TTLs.

Decision rule. From the price ratios alone (1h write 2x input, 5m write
1.25x, cache read 0.025x for Fable 5.1; 0.1x for older tiers) the 1h TTL
breaks even when re-writes after 5-to-60-minute gaps exceed roughly 38% of
all write tokens. Measured 2026-09-02 on one workstation: 2.8% for subagents,
so both keys stay unset (#3876). Re-run when fan-out patterns change.

Usage:
    python3 scripts/measure-cache-gaps.py [--days 14] [--out PATH]

Reads only. Writes one markdown report (default: stdout).
"""
from __future__ import annotations

import argparse
import glob
import json
import os
import sys
import time
from collections import defaultdict
from datetime import datetime

BUCKETS = [(0, 60, "<1m"), (60, 300, "1-5m"), (300, 900, "5-15m"), (900, 3600, "15-60m"), (3600, 1e12, ">60m")]
ORDER = ["first", "<1m", "1-5m", "5-15m", "15-60m", ">60m"]
# Fable 5.1 list prices per MTok: 5m write, 1h write, cache read.
P_W5, P_W1H, P_RD = 12.5, 20.0, 0.25


def bucket(gap: float) -> str:
    for lo, hi, name in BUCKETS:
        if lo <= gap < hi:
            return name
    return "?"


def iso_to_ts(s: str) -> float | None:
    try:
        return datetime.fromisoformat(s.replace("Z", "+00:00")).timestamp()
    except ValueError:
        return None


def collect(root: str, days: int) -> tuple[dict, dict, dict]:
    cutoff = time.time() - days * 86400
    files = [f for f in glob.glob(os.path.join(root, "**", "*.jsonl"), recursive=True) if os.path.getmtime(f) >= cutoff]
    kinds: dict[str, list[str]] = {"main": [], "subagent": []}
    for f in files:
        if os.path.basename(f).startswith("agent-") or "/subagents/" in f:
            kinds["subagent"].append(f)
        elif "/memory/" in f or "/tool-results/" in f:
            continue
        else:
            kinds["main"].append(f)

    stats = {k: defaultdict(lambda: defaultdict(int)) for k in kinds}
    models = {k: defaultdict(lambda: defaultdict(int)) for k in kinds}
    counts = {k: {"files": len(v), "turns": 0} for k, v in kinds.items()}

    for kind, flist in kinds.items():
        for f in flist:
            prev_ts = None
            try:
                fh = open(f, "r", errors="replace")
            except OSError:
                continue
            with fh:
                for line in fh:
                    if '"usage"' not in line or '"assistant"' not in line:
                        continue
                    try:
                        rec = json.loads(line)
                    except ValueError:
                        continue
                    if rec.get("type") != "assistant":
                        continue
                    msg = rec.get("message") or {}
                    usage = msg.get("usage") or {}
                    ts = iso_to_ts(rec.get("timestamp") or "")
                    if ts is None:
                        continue
                    gap = (ts - prev_ts) if prev_ts is not None else -1
                    # Streaming writes several assistant rows per API turn with
                    # identical usage; keep the first row of each turn.
                    if prev_ts is not None and gap < 0.5:
                        continue
                    cc = usage.get("cache_creation_input_tokens") or 0
                    cr = usage.get("cache_read_input_tokens") or 0
                    ccd = usage.get("cache_creation") or {}
                    c5 = ccd.get("ephemeral_5m_input_tokens") or 0
                    c1 = ccd.get("ephemeral_1h_input_tokens") or 0
                    b = "first" if gap < 0 else bucket(gap)
                    s = stats[kind][b]
                    s["turns"] += 1
                    s["creation"] += cc
                    s["read"] += cr
                    if c1 and not c5:
                        s["turns_1h"] += 1
                    elif c5 and not c1:
                        s["turns_5m"] += 1
                    m = models[kind][msg.get("model") or "unknown"]
                    m["turns"] += 1
                    m["creation"] += cc
                    m["read"] += cr
                    if b in ("5-15m", "15-60m"):
                        m["rewrite_5m_to_1h"] += cc
                    prev_ts = ts
                    counts[kind]["turns"] += 1
    return stats, models, counts


def report(stats: dict, models: dict, counts: dict, days: int) -> str:
    out = [f"# Prompt-cache gap measurement, last {days} days, generated {time.strftime('%Y-%m-%d %H:%M %Z')}"]
    out.append(
        "files: main={} subagent={}; assistant turns: main={} subagent={}".format(
            counts["main"]["files"], counts["subagent"]["files"], counts["main"]["turns"], counts["subagent"]["turns"]
        )
    )
    break_even = (P_W1H - P_W5) / (P_W1H - P_RD) * 100
    for kind in ("main", "subagent"):
        out.append("")
        out.append(f"## {kind} transcripts, by gap since previous turn")
        out.append("| gap | turns | cache_creation MTok | cache_read MTok | creation share | turns on 5m / 1h TTL |")
        out.append("|---|---|---|---|---|---|")
        total_c = sum(stats[kind][b]["creation"] for b in ORDER) or 1
        for b in ORDER:
            s = stats[kind][b]
            if not s["turns"]:
                continue
            out.append(
                f"| {b} | {s['turns']} | {s['creation'] / 1e6:.2f} | {s['read'] / 1e6:.2f} | "
                f"{s['creation'] / total_c * 100:.1f}% | {s['turns_5m']} / {s['turns_1h']} |"
            )
        fresh = sum(stats[kind][b]["creation"] for b in ("first", "<1m", "1-5m"))
        avoidable = sum(stats[kind][b]["creation"] for b in ("5-15m", "15-60m"))
        beyond = stats[kind][">60m"]["creation"]
        cost_5m = (fresh + avoidable + beyond) * P_W5 / 1e6
        cost_1h = (fresh + beyond) * P_W1H / 1e6 + avoidable * P_RD / 1e6
        share = avoidable / total_c * 100
        out.append("")
        out.append(
            f"avoidable re-writes (5 to 60 min gaps): {avoidable / 1e6:.2f} MTok = {share:.1f}% of write tokens; "
            f"break-even for a 1h TTL is {break_even:.0f}%"
        )
        out.append(f"Fable 5.1 list-price lens, writes only: 5m TTL ${cost_5m:,.2f} vs 1h TTL ${cost_1h:,.2f} (delta ${cost_1h - cost_5m:+,.2f})")
        out.append("")
        out.append(f"### {kind} by model")
        out.append("| model | turns | creation MTok | read MTok | creation after 5-60m gap MTok |")
        out.append("|---|---|---|---|---|")
        for name, m in sorted(models[kind].items(), key=lambda kv: -kv[1]["creation"])[:8]:
            out.append(f"| {name} | {m['turns']} | {m['creation'] / 1e6:.2f} | {m['read'] / 1e6:.2f} | {m['rewrite_5m_to_1h'] / 1e6:.2f} |")
    return "\n".join(out) + "\n"


def main() -> int:
    ap = argparse.ArgumentParser(description=(__doc__ or "").split("\n\n")[0])
    ap.add_argument("--days", type=int, default=14)
    ap.add_argument("--root", default=os.path.expanduser("~/.claude/projects"))
    ap.add_argument("--out", default="-", help="report path, '-' for stdout")
    args = ap.parse_args()
    stats, models, counts = collect(args.root, args.days)
    text = report(stats, models, counts, args.days)
    if args.out == "-":
        sys.stdout.write(text)
    else:
        with open(args.out, "w") as fh:
            fh.write(text)
        print(f"written: {args.out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
